<template><div class="scheme-manager"><el-dialog title="切换方案" :visible.sync="switchVisible" width="700px"><el-table :data="schemes" highlight-current-row @row-click="handleSwitch"><el-table-column type="index" label="#" width="50" /><el-table-column prop="name" label="方案名称" min-width="140" /><el-table-column prop="description" label="描述" show-overflow-tooltip min-width="160" /><el-table-column prop="updated_at" label="更新时间" width="160" /><el-table-column label="状态" width="80"><template slot-scope="{row}"><el-tag v-if="row.is_active" size="mini" type="success">激活</el-tag></template></el-table-column><el-table-column label="操作" width="160"><template slot-scope="{row}"><el-button v-if="!row.is_active" type="text" size="mini" @click.stop="handleSwitch(row)">切换</el-button><el-button type="text" size="mini" @click.stop="handleDuplicate(row)">复制</el-button><el-popconfirm v-if="!row.is_active" title="确认删除此方案？" @confirm="$emit('delete',row)"><el-button slot="reference" type="text" size="mini" style="color:#f56c6c">删除</el-button></el-popconfirm></template></el-table-column></el-table></el-dialog><el-dialog title="新建方案" :visible.sync="createVisible" width="420px"><el-form label-width="80px"><el-form-item label="方案名称" required><el-input v-model="createForm.name" placeholder="请输入方案名称" maxlength="50" /></el-form-item><el-form-item label="方案描述"><el-input v-model="createForm.description" type="textarea" :rows="2" maxlength="200" /></el-form-item></el-form><span slot="footer"><el-button @click="$emit('close')">取消</el-button><el-button type="primary" @click="$emit('create',createForm)">确定</el-button></span></el-dialog><el-dialog title="导入配置" :visible.sync="importVisible" width="500px"><el-upload drag accept=".json" :auto-upload="false" :on-change="handleImportChange" :limit="1"><i class="el-icon-upload" /><div class="el-upload__text">将 JSON 配置文件拖到此处，或<em>点击选择</em></div></el-upload><div style="margin-top:12px"><el-input v-model="importName" placeholder="导入后的方案名称" /></div><span slot="footer"><el-button @click="$emit('close')">取消</el-button><el-button type="primary" @click="$emit('import',{data:importData,name:importName})">导入</el-button></span></el-dialog></div></template>
<script>export default{name:'SchemeManager',props:{visible:{type:Boolean,default:false},dialogType:{type:String,default:''},schemes:{type:Array,default:()=>[]}},emits:['close','switch-scheme','create','duplicate','delete','import'],data(){return{createForm:{name:'',description:''},importData:null,importName:''}},computed:{switchVisible:{get(){return this.visible&&this.dialogType==='switch'},set(v){if(!v)this.$emit('close')}},createVisible:{get(){return this.visible&&this.dialogType==='new'},set(v){if(!v)this.$emit('close')}},importVisible:{get(){return this.visible&&this.dialogType==='import'},set(v){if(!v)this.$emit('close')}}},watch:{dialogType(v){if(v==='new')this.createForm={name:'',description:''}}},methods:{handleSwitch(s){this.$emit('switch-scheme',s)},handleDuplicate(s){this.$emit('duplicate',{id:s.id,name:(s?.name||'')+' - 副本'})},handleImportChange(f){const r=new FileReader();r.onload=(e)=>{try{this.importData=JSON.parse(e.target.result)}catch{this.$message.error('JSON 格式无效')}};r.readAsText(f.raw)}}}</script>
